import{c as a,Q as t,j as r,m as i}from"./chunks/framework.g_l1frA7.js";const g=JSON.parse('{"title":"Recurring","description":"","frontmatter":{},"headers":[],"relativePath":"guide/recurring.md","filePath":"guide/recurring.md","lastUpdated":null}'),n={name:"guide/recurring.md"};function o(s,e,c,d,h,l){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="recurring" tabindex="-1">Recurring <a class="header-anchor" href="#recurring" aria-label="Permalink to &quot;Recurring&quot;">​</a></h1><p>Find subscriptions and bills before they surprise you.</p><h2 id="two-views" tabindex="-1">Two views <a class="header-anchor" href="#two-views" aria-label="Permalink to &quot;Two views&quot;">​</a></h2><ul><li><strong>Calendar</strong> — recurring items placed on the dates they are expected. Useful for the next 30-day outlook.</li><li><strong>List</strong> — every detected recurring group, with cadence, typical amount, and history count.</li></ul><p>Source: <code>finsight-core::subscriptions</code> and <code>finsight-core::recurring</code>. Detection is deterministic over merchant + amount tolerance + interval regularity; the LLM is never asked “is this recurring?”.</p><h2 id="detection" tabindex="-1">Detection <a class="header-anchor" href="#detection" aria-label="Permalink to &quot;Detection&quot;">​</a></h2><p>A group becomes recurring when it hits the cadence and regularity thresholds (e.g. three charges from the same merchant within ±10% amount and ±3 days of a 30-day cadence). Variable-amount bills (utilities) match on merchant and cadence, not exact amount.</p><h2 id="managing" tabindex="-1">Managing <a class="header-anchor" href="#managing" aria-label="Permalink to &quot;Managing&quot;">​</a></h2><ul><li><strong>Confirm</strong> — mark a group as a known subscription (adds it to the calendar even if amount drifts).</li><li><strong>Dismiss</strong> — hide a spurious group; it will not reappear unless the cadence changes.</li><li><strong>Edit</strong> — adjust merchant grouping or cadence. Edits are local; no data leaves the machine.</li></ul><h2 id="sync-with-cash-flow" tabindex="-1">Sync with Cash Flow <a class="header-anchor" href="#sync-with-cash-flow" aria-label="Permalink to &quot;Sync with Cash Flow&quot;">​</a></h2><p>Confirmed recurring items feed the cash-flow calendar and the safe-to-spend calculation as scheduled outflows. A skipped month does not break the model — the forecast exposes the assumption and shows the warning.</p><p>See also: <a href="/FinSight/guide/cashflow">Cash Flow</a>, <a href="/FinSight/guide/insights">Insights</a>.</p>',12)])])}const m=a(n,[["render",o]]);export{g as __pageData,m as default};
